  "supportive_card_ids": ["C02","C15","C21","C26","C29","C31","C33","C40","C46","C44","C55","C54","C48","C53","C59","C49","C57"],
  "contradictory_card_ids": ["C25","C51","C56","C58"],
  "prediction_basis_card_ids": ["C02","C15","C21","C26","C29","C31","C33","C40","C46","C44","C55","C54","C48","C53","C59","C49","C57"],
  "claims": [
    {
      "claim": "Direct absolute F measurements for baclofen (73–86% in humans, 69% in dogs) and levodopa (63.6–86.4% across fasted/fed IR/CR formulations) show that highly polar, zwitterionic amino-acid-like drugs can exceed F=20% despite unfavorable passive permeability descriptors.",
      "card_ids": ["C02","C15","C21","C26","C29","C31","C33"]
    },
    {
      "claim": "Oral beta-lactam exposure records show meaningful systemic absorption after oral dosing: ampicillin Cmax 9.53 µg/mL after 500 mg sultamicillin, amoxicillin Cmax 11.4 µg/mL after 200 mg in dogs, and cefpodoxime Cmax 1.32 mg/L after 100 mg.",
      "card_ids": ["C40","C46","C44"]
    },
    {
      "claim": "L4 shows favorable amoxicillin solubility (4.4–7.69 mg/mL at pH 1.2–6.8) and moderate cephalexin Caco-2 permeability (8.42×10^-7 cm/s); amoxicillin's lack of PAMPA permeation illustrates that low passive permeability does not preclude oral absorption for this aminocephalosporin class.",
      "card_ids": ["C54","C48","C53","C59","C49","C55","C57"]
    },
    {
      "claim": "Low-permeability records for piperacillin (3.25×10^-8 to 3.22×10^-7 cm/s) and the indirect rat Cmax inference for baclofen metabolites are not transferable to the query because they lack the alpha-amino-p-hydroxyphenylglycyl/aminocephalosporin absorption motif or are not direct F measurements.",
      "card_ids": ["C25","C51","C56","C58"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C48","C49","C50","C51","C52","C53","C54","C55","C56","C57","C58","C59"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for cefatrizine is present in the supplied cards.",
    "L4 permeability/solubility records are for analogs (amoxicillin, cephalexin, piperacillin) rather than the query; no direct Caco-2/PAMPA or solubility value for cefatrizine is supplied.",
    "L3 Cmax records lack matched IV AUC, so they do not quantify absolute F.",
    "PepT1/transporter-mediated absorption and gastrointestinal stability of the query are not directly measured.",
    "C52 is an outlier mixture/pH condition and is not used as material evidence.",
    "Species, formulation, and prandial differences prevent a numeric F estimate."
  ],
  "decision_summary": "Prediction remains high and is strengthened by L4: amoxicillin solubility is favorable (4.4–7.69 mg/mL), cephalexin shows moderate Caco-2 permeability (8.42×10^-7 cm/s), and amoxicillin's lack of PAMPA permeation shows that low passive permeability does not preclude oral absorption for this aminocephalosporin class. Piperacillin low-permeability records and the indirect rat Cmax inference are structurally non-transferable. The query cefatrizine shares the alpha-amino-p-hydroxyphenylglycyl cephem scaffold with orally absorbed beta-lactams; no affirmative threshold-relevant evidence supports F<20%. Confidence remains moderate because no direct query F is available."
}

